if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854' and md5(to_jsonb(t)::text)='e4c585c393445988b58fb1b2acae876d')then raise exception 'NATIVE_DEFINITION_CHANGED:gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_e2dde047db73628d${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","revision":1,"language":"es","name":"Daga del Umbral · variante de Stix","aliases":["Daga del Umbral"],"baseDefinitionId":"recovery:gm:equipment:f92abc1a-849e-47e0-995b-0602c7156af8","origin":"campaign","sources":[{"id":"original:af772b9c99899190844411944a69deb276f15333962b06d1434c26c337a5839a","kind":"legacy","title":"Daga del Umbral","language":"es","rulesEdition":null,"locator":"gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","verified":false},{"id":"original:cb6ee5a619b222ffe82fbe5dc106180a8e11292b94d8b51402f4983dc92a0803","kind":"legacy","title":"Daga del Umbral","language":"es","rulesEdition":null,"locator":"gm:equipment:f92abc1a-849e-47e0-995b-0602c7156af8","verified":false},{"id":"ece-authored-rule","kind":"campaign","title":"ECE · regla de campaña conservada","language":"es","rulesEdition":"2014","locator":"gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","verified":true}],"category":"weapon","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":["magic"],"weight":{"value":1,"unit":"lb"},"economy":{"basePrice":null,"campaignPrice":{"quantity":500,"unit":"gp"},"explanation":"Precio de campaña anterior conservado por separado; cero no se interpreta como precio oficial ni modifica el stock."},"description":[{"id":"campaign-text-0","section":"rules","provenance":"campaign","sourceIds":["ece-authored-rule"],"type":"paragraph","text":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea."},{"id":"campaign-feature-1","section":"rules","provenance":"campaign","sourceIds":["ece-authored-rule"],"type":"paragraph","text":"Hoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional."},{"id":"campaign-existing-effect","section":"rules","provenance":"campaign","sourceIds":["ece-authored-rule"],"type":"paragraph","text":"Hoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad."}],"requirements":{"attunement":true,"bearer":[{"kind":"other","keys":["chr_2de8dab74a76cdd8d2b0d37cc84725ea","chr_c0d4a321021830d8dc5e7313710d762a"],"explanation":"Hoja Fásica es exclusiva de la variante de Stix, según indicación del GM. No trasladarla a otras dagas."}],"presence":"held","explanation":"La sintonización y restricciones se aplican a los poderes mágicos, no a la mera posesión ni al uso mundano de un arma."},"weapon":null,"armor":null,"resources":[{"id":"salto","name":"salto","kind":"uses","maximum":1,"unit":"usos","recovery":{"kind":"event","event":"short-rest","explanation":"Un descanso corto o largo recupera el uso.","amount":{"kind":"full"}},"exhaustion":"No se puede activar sin el recurso necesario."}],"capabilities":[{"id":"phase-blade","name":"Hoja Fásica · Stix","activation":"trigger","trigger":"Stix obtiene un 20 natural atacando con esta variante.","requirements":{"attunement":true,"bearer":[{"kind":"other","keys":["chr_2de8dab74a76cdd8d2b0d37cc84725ea","chr_c0d4a321021830d8dc5e7313710d762a"],"explanation":"Hoja Fásica es exclusiva de la variante de Stix, según indicación del GM. No trasladarla a otras dagas."}],"presence":"held","explanation":"La sintonización y restricciones se aplican a los poderes mágicos, no a la mera posesión ni al uso mundano de un arma."},"target":"Portador","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"phase-blade-0","condition":"Solo con un 20 natural en un ataque de Stix. Los dados adicionales del ataque siguen la regla de críticos de 2014.","kind":"damage","expression":"1d6","damageType":"force","timing":"critical"}],"execution":{"mode":"automatic","handler":"equipment-weapon-hit","explanation":"Daño del arma según el resultado del impacto; los bonos fijos no se duplican e